package com.dpworld.fms.routing;import static org.junit.jupiter.api.Assertions.*;import com.dpworld.fms.domain.GeoPoint;import java.util.*;import org.junit.jupiter.api.Test;
class GpsMapMatcherTest{@Test void matchesNearbyTelemetryUsingHeadingAndContinuity(){var a=new MapNode("A",new GeoPoint(25,55));var b=new MapNode("B",new GeoPoint(25,55.001));var edge=new RoadSegment(UUID.randomUUID().toString(),"A","B",100,30,1,1,false,false,Set.of(),0,0,0);var match=new GpsMapMatcher(List.of(a,b),List.of(edge),40).match(new GeoPoint(25.00005,55.0005),90,null);assertNotNull(match);assertEquals(edge.id(),match.segmentId());assertTrue(match.distanceMetres()<10);}@Test void leavesDistantTelemetryUnmatched(){var a=new MapNode("A",new GeoPoint(25,55));var b=new MapNode("B",new GeoPoint(25,55.001));var edge=new RoadSegment(UUID.randomUUID().toString(),"A","B",100,30,1,1,false,false,Set.of(),0,0,0);assertNull(new GpsMapMatcher(List.of(a,b),List.of(edge),20).match(new GeoPoint(25.01,55.01),90,null));}}
